package __PACKAGE__;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * COBOL storage rules as the original program applies them (GnuCOBOL -std=ibm -fsign=EBCDIC, the oracle's dialect). The
 * generated record classes store through these rules; the public helpers apply the same rules to values the program keeps
 * in ordinary Java fields (counters, totals, flags). Generated by the MlCpu record kit; do not edit.
 */
public final class Pic {
    private Pic() {}

    // ------------------------------------------------------------------ helpers for PICTUREs as written in the COBOL source

    /**
     * The value a numeric item with this PICTURE holds after a MOVE, ADD or COMPUTE without ROUNDED: fraction digits beyond
     * the scale are cut, integer digits beyond the PICTURE are lost on the left, and an unsigned item keeps the magnitude.
     * {@code fit(new BigDecimal("-1234567.891"), "S9(5)V99")} is -34567.89; {@code fit(new BigDecimal("-5"), "9(3)")} is 5.
     */
    public static BigDecimal fit(BigDecimal value, String picture) {
        Shape s = Shape.of(picture);
        return new BigDecimal(scaled(value, s.scale, s.digits, s.signed, false), s.scale);
    }

    /** As {@link #fit} with ROUNDED (half away from zero at the last fraction digit). */
    public static BigDecimal fitRounded(BigDecimal value, String picture) {
        Shape s = Shape.of(picture);
        return new BigDecimal(scaled(value, s.scale, s.digits, s.signed, true), s.scale);
    }

    /** True when the value has more integer digits than the PICTURE holds: the ON SIZE ERROR condition. */
    public static boolean sizeError(BigDecimal value, String picture) {
        Shape s = Shape.of(picture);
        return value.setScale(s.scale, RoundingMode.DOWN).unscaledValue().abs().compareTo(BigInteger.TEN.pow(s.digits)) >= 0;
    }

    /**
     * The text a numeric-edited item holds after {@code MOVE value TO item}: zero suppression (Z, *), insertion (, . B 0 /),
     * fixed and floating signs (+ - CR DB) and currency ($), with the same truncation as {@link #fit}.
     * {@code edit(new BigDecimal("-1234.5"), "-ZZZ,ZZZ,ZZZ.ZZ")} is {@code "-      1,234.50"}; a zero amount in an all-Z
     * picture is blank.
     */
    public static String edit(BigDecimal value, String picture) {
        return edit(value, picture, false);
    }

    /** {@link #edit} for an item with BLANK WHEN ZERO. */
    public static String edit(BigDecimal value, String picture, boolean blankWhenZero) {
        Shape s = Shape.of(picture);
        if (!s.edited) throw new IllegalArgumentException(picture + " is not a numeric-edited PICTURE");
        return format(value.setScale(Math.max(s.scale, 0), RoundingMode.DOWN), s.expanded, s.scale, blankWhenZero);
    }

    /**
     * What {@code DISPLAY item} prints for a numeric item with this PICTURE and USAGE ("DISPLAY", "COMP-3", "COMP",
     * "COMP-5"); {@code style} is {@code ctx.displayNumeric()}. Under "gnucobol" a signed DISPLAY item prints its digits then
     * its sign ("0000012+"), a binary item prints the digits its byte size holds, and an unsigned DISPLAY item prints its digits.
     */
    public static String display(BigDecimal value, String picture, String usage, String style) {
        Shape s = Shape.of(picture);
        boolean gnu = "gnucobol".equalsIgnoreCase(style);
        String u = usage == null ? "DISPLAY" : usage.trim().toUpperCase();
        if (u.equals("DISPLAY")) {
            byte[] b = new byte[s.digits];
            putZoned(b, 0, s.digits, s.digits, s.scale, s.signed, false, false, value);
            String raw = new String(b, StandardCharsets.ISO_8859_1);
            if (!gnu || !s.signed) return raw;
            BigDecimal v = getZoned(b, 0, s.digits, s.scale, true, false, false);
            return pad(v.unscaledValue().abs().toString(), s.digits) + (v.signum() < 0 ? '-' : '+');
        }
        boolean binary = u.equals("COMP") || u.equals("COMP-4") || u.equals("BINARY") || u.equals("COMPUTATIONAL") || u.equals("COMPUTATIONAL-4");
        boolean comp5 = u.equals("COMP-5") || u.equals("COMPUTATIONAL-5");
        BigDecimal v;
        int n = s.digits;
        if (binary || comp5) {
            int len = s.digits <= 4 ? 2 : s.digits <= 9 ? 4 : 8;
            byte[] b = new byte[len];
            putBinary(b, 0, len, s.scale, s.signed, value);
            v = getBinary(b, 0, len, s.scale, s.signed);
            if (gnu || comp5) n = switch (len) { case 2 -> 5; case 4 -> 10; default -> s.signed ? 19 : 20; };
        } else {
            int len = s.digits / 2 + 1;
            byte[] b = new byte[len];
            putPacked(b, 0, len, s.digits, s.scale, s.signed, value);
            v = getPacked(b, 0, len, s.scale);
        }
        String digits = pad(v.unscaledValue().abs().toString(), n);
        if (gnu) return s.signed ? (v.signum() < 0 ? "-" : "+") + digits : digits;
        if (s.signed && v.signum() < 0) return digits.substring(0, digits.length() - 1) + (char) overpunch(digits.charAt(digits.length() - 1) - '0', true);
        return digits;
    }

    /** {@code MOVE value TO item} for a PIC X(length) item: left-justified, space padded, truncated on the right. */
    public static String text(String value, int length) {
        byte[] b = new byte[length];
        putText(b, 0, length, value, false);
        return new String(b, StandardCharsets.ISO_8859_1);
    }

    /** The digits an unsigned PIC 9(length) item holds for {@code value}: zero padded, high-order digits lost. */
    public static String digits(long value, int length) {
        return pad(BigInteger.valueOf(value).abs().toString(), length);
    }

    // ------------------------------------------------------------------ record codecs (used by the generated classes)

    static byte[] filled(int length, byte b) {
        byte[] r = new byte[length];
        Arrays.fill(r, b);
        return r;
    }

    /** MOVE of a group (or a whole record) to an area of {@code len} bytes: copied, then space padded or truncated. */
    static byte[] moved(byte[] from, int len) {
        byte[] r = new byte[len];
        int c = Math.min(from.length, len);
        System.arraycopy(from, 0, r, 0, c);
        Arrays.fill(r, c, len, (byte) ' ');
        return r;
    }

    static String getText(byte[] b, int off, int len) {
        return new String(b, off, len, StandardCharsets.ISO_8859_1);
    }

    /** Alphanumeric MOVE: left-justified (or right-justified for JUSTIFIED RIGHT), space filled, truncated. */
    static void putText(byte[] b, int off, int len, String value, boolean right) {
        byte[] s = (value == null ? "" : value).getBytes(StandardCharsets.ISO_8859_1);
        int c = Math.min(s.length, len);
        if (!right) {
            System.arraycopy(s, 0, b, off, c);
            Arrays.fill(b, off + c, off + len, (byte) ' ');
        } else {
            System.arraycopy(s, s.length - c, b, off + len - c, c);
            Arrays.fill(b, off, off + len - c, (byte) ' ');
        }
    }

    static void fill(byte[] b, int off, int len, byte value) {
        Arrays.fill(b, off, off + len, value);
    }

    /** VALUE ALL 'literal': the literal repeated over the item. */
    static void putAll(byte[] b, int off, int len, String pattern) {
        byte[] p = pattern.getBytes(StandardCharsets.ISO_8859_1);
        for (int i = 0; i < len; i++) b[off + i] = p[i % p.length];
    }

    static BigDecimal getZoned(byte[] b, int off, int len, int scale, boolean signed, boolean sep, boolean lead) {
        boolean neg = false;
        int ds = off, de = off + len;
        if (signed && sep) {
            byte s = lead ? b[off] : b[off + len - 1];
            neg = s == '-';
            if (lead) ds++; else de--;
        }
        BigInteger u = BigInteger.ZERO;
        long acc = 0;
        int count = 0;
        for (int i = ds; i < de; i++) {
            int c = b[i] & 0xFF;
            int d;
            if (signed && !sep && (lead ? i == ds : i == de - 1)) {
                int[] ds2 = unpunch(c);
                d = ds2[0];
                if (ds2[1] < 0) neg = true;
            } else {
                d = c & 0x0F;
                if (d > 9) d = 0;
            }
            if (count < 18) acc = acc * 10 + d;
            else {
                if (count == 18) u = BigInteger.valueOf(acc);
                u = u.multiply(BigInteger.TEN).add(BigInteger.valueOf(d));
            }
            count++;
        }
        BigInteger unscaled = count > 18 ? u : BigInteger.valueOf(acc);
        return new BigDecimal(neg ? unscaled.negate() : unscaled, scale);
    }

    static void putZoned(byte[] b, int off, int len, int digits, int scale, boolean signed, boolean sep, boolean lead, BigDecimal value) {
        BigInteger u = scaled(value, scale, digits, signed, false);
        boolean neg = u.signum() < 0;
        String d = u.abs().toString();
        int ds = off;
        if (signed && sep) {
            if (lead) { b[off] = (byte) (neg ? '-' : '+'); ds = off + 1; }
            else b[off + len - 1] = (byte) (neg ? '-' : '+');
        }
        for (int i = 0; i < digits; i++) {
            int src = d.length() - digits + i;
            b[ds + i] = (byte) (src >= 0 ? d.charAt(src) : '0');
        }
        if (signed && !sep) {
            int sp = lead ? ds : ds + digits - 1;
            b[sp] = (byte) overpunch(b[sp] - '0', neg);
        }
    }

    static BigDecimal getPacked(byte[] b, int off, int len, int scale) {
        BigInteger u = BigInteger.ZERO;
        for (int i = 0; i < len; i++) {
            int v = b[off + i] & 0xFF;
            int hi = v >> 4, lo = v & 0x0F;
            u = u.multiply(BigInteger.TEN).add(BigInteger.valueOf(hi > 9 ? 0 : hi));
            if (i < len - 1) u = u.multiply(BigInteger.TEN).add(BigInteger.valueOf(lo > 9 ? 0 : lo));
        }
        int sign = b[off + len - 1] & 0x0F;
        return new BigDecimal(sign == 0x0D || sign == 0x0B ? u.negate() : u, scale);
    }

    static void putPacked(byte[] b, int off, int len, int digits, int scale, boolean signed, BigDecimal value) {
        BigInteger u = scaled(value, scale, digits, signed, false);
        boolean neg = u.signum() < 0;
        String d = u.abs().toString();
        int nd = len * 2 - 1;
        String digs = d.length() >= nd ? d.substring(d.length() - nd) : "0".repeat(nd - d.length()) + d;
        int sign = signed ? (neg ? 0x0D : 0x0C) : 0x0F;
        for (int i = 0; i < len; i++) {
            int hi = digs.charAt(i * 2) - '0';
            int lo = i == len - 1 ? sign : digs.charAt(i * 2 + 1) - '0';
            b[off + i] = (byte) ((hi << 4) | lo);
        }
    }

    static BigDecimal getBinary(byte[] b, int off, int len, int scale, boolean signed) {
        byte[] raw = Arrays.copyOfRange(b, off, off + len);
        return new BigDecimal(signed ? new BigInteger(raw) : new BigInteger(1, raw), scale);
    }

    /** COMP / COMP-5: truncated to the binary size, not to the PICTURE (the oracle's binary-truncate: no). */
    static void putBinary(byte[] b, int off, int len, int scale, boolean signed, BigDecimal value) {
        BigInteger u = value.setScale(scale, RoundingMode.DOWN).unscaledValue();
        if (!signed) u = u.abs();
        int bits = len * 8 - (signed ? 1 : 0);
        if (u.abs().compareTo(BigInteger.ONE.shiftLeft(bits)) >= 0) {
            BigInteger mod = BigInteger.ONE.shiftLeft(len * 8);
            BigInteger r = u.mod(mod);
            if (signed && r.testBit(len * 8 - 1)) r = r.subtract(mod);
            u = r;
        }
        byte[] raw = u.toByteArray();
        byte fill = (byte) (u.signum() < 0 ? 0xFF : 0x00);
        for (int i = 0; i < len; i++) {
            int src = raw.length - len + i;
            b[off + i] = src >= 0 ? raw[src] : fill;
        }
    }

    /** MOVE to a numeric-edited item; {@code picture} is expanded (no repeat counts). */
    static void putEdited(byte[] b, int off, int len, String picture, int scale, boolean blankWhenZero, BigDecimal value) {
        putText(b, off, len, format(value.setScale(Math.max(scale, 0), RoundingMode.DOWN), picture, scale, blankWhenZero), false);
    }

    /** MOVE of alphanumeric text to an alphanumeric-edited item: B, 0 and / are inserted, the text fills the other positions. */
    static void putAlnumEdited(byte[] b, int off, int len, String picture, String value) {
        byte[] src = (value == null ? "" : value).getBytes(StandardCharsets.ISO_8859_1);
        byte[] out = new byte[len];
        int si = 0, oi = 0;
        for (int i = 0; i < picture.length() && oi < len; i++) {
            char c = picture.charAt(i);
            out[oi++] = switch (c) {
                case 'B' -> (byte) ' ';
                case '0' -> (byte) '0';
                case '/' -> (byte) '/';
                default -> si < src.length ? src[si++] : (byte) ' ';
            };
        }
        putText(b, off, len, new String(out, 0, oi, StandardCharsets.ISO_8859_1), false);
    }

    // ------------------------------------------------------------------ internals

    /** setScale (cut or rounded), magnitude only when unsigned, then the integer digits beyond the PICTURE dropped. */
    static BigInteger scaled(BigDecimal value, int scale, int digits, boolean signed, boolean rounded) {
        BigInteger u = value.setScale(scale, rounded ? RoundingMode.HALF_UP : RoundingMode.DOWN).unscaledValue();
        if (!signed) u = u.abs();
        BigInteger cap = BigInteger.TEN.pow(digits);
        if (u.abs().compareTo(cap) >= 0) u = u.signum() < 0 ? u.negate().mod(cap).negate() : u.mod(cap);
        return u;
    }

    static String pad(String d, int n) {
        return d.length() > n ? d.substring(d.length() - n) : "0".repeat(n - d.length()) + d;
    }

    /** Sign overpunch of the last zoned digit (EBCDIC convention): { A-I for +0..+9, } J-R for -0..-9. */
    static int overpunch(int digit, boolean negative) {
        if (negative) return digit == 0 ? '}' : 'J' + digit - 1;
        return digit == 0 ? '{' : 'A' + digit - 1;
    }

    /** {digit, sign}: sign -1, +1 or 0 (a plain digit). Also reads GnuCOBOL's ASCII overpunch (p-y) and EBCDIC zones. */
    static int[] unpunch(int c) {
        if (c >= '0' && c <= '9') return new int[]{c - '0', 0};
        if (c == '{') return new int[]{0, 1};
        if (c >= 'A' && c <= 'I') return new int[]{c - 'A' + 1, 1};
        if (c == '}') return new int[]{0, -1};
        if (c >= 'J' && c <= 'R') return new int[]{c - 'J' + 1, -1};
        if (c >= 'p' && c <= 'y') return new int[]{c - 'p', -1};
        if (c >= 0xC0 && c <= 0xC9) return new int[]{c - 0xC0, 1};
        if (c >= 0xD0 && c <= 0xD9) return new int[]{c - 0xD0, -1};
        if (c >= 0xF0 && c <= 0xF9) return new int[]{c - 0xF0, 0};
        int d = c & 0x0F;
        return new int[]{d > 9 ? 0 : d, 0};
    }

    /** Numeric editing per the COBOL standard (the faithful translation's rules); {@code p} is expanded and upper case. */
    static String format(BigDecimal value, String p, int scale, boolean blankWhenZero) {
        int n = p.length();
        char floatCh = 0;
        int floatFirst = -1, floatLast = -1;
        for (int i = 0; i < n; i++) {
            char c = p.charAt(i);
            if (c == '+' || c == '-' || c == '$') {
                int count = 0, j = i, last = i;
                while (j < n && (p.charAt(j) == c || ((p.charAt(j) == ',' || p.charAt(j) == 'B' || p.charAt(j) == '0' || p.charAt(j) == '/') && j + 1 < n && p.charAt(j + 1) == c))) {
                    if (p.charAt(j) == c) { count++; last = j; }
                    j++;
                }
                if (count >= 2) { floatCh = c; floatFirst = i; floatLast = last; }
                break;
            }
            if (c == '9' || c == 'Z' || c == '*' || c == '.' || c == 'V') break;
        }
        int point = -1;
        for (int i = 0; i < n; i++) if (p.charAt(i) == '.' || p.charAt(i) == 'V') { point = i; break; }
        int intPos = 0, fracPos = 0;
        boolean anyNine = false;
        for (int i = 0; i < n; i++) {
            char c = p.charAt(i);
            boolean digitPos = c == '9' || c == 'Z' || c == '*' || (floatCh != 0 && c == floatCh && i > floatFirst && i <= floatLast);
            if (c == '9') anyNine = true;
            if (!digitPos) continue;
            if (point >= 0 && i > point) fracPos++; else intPos++;
        }
        boolean neg = value.signum() < 0;
        BigDecimal abs = value.abs().setScale(fracPos, RoundingMode.DOWN);
        String digits = abs.unscaledValue().toString();
        int total = intPos + fracPos;
        if (digits.length() > total) digits = digits.substring(digits.length() - total);
        while (digits.length() < total) digits = "0" + digits;
        boolean isZero = digits.chars().allMatch(ch -> ch == '0');
        if (blankWhenZero && isZero) return " ".repeat(lengthOf(p));
        char suppress = p.indexOf('*') >= 0 ? '*' : ' ';
        boolean allSuppress = !anyNine && (p.indexOf('Z') >= 0 || p.indexOf('*') >= 0 || floatCh != 0);
        if (allSuppress && isZero) {
            if (suppress == '*') {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < n; i++) {
                    char c = p.charAt(i);
                    if (c == 'V') continue;
                    sb.append(c == '.' ? '.' : '*');
                }
                return sb.toString();
            }
            return " ".repeat(lengthOf(p));
        }
        StringBuilder out = new StringBuilder();
        int di = 0;
        boolean started = false;
        for (int i = 0; i < n; i++) {
            char c = p.charAt(i);
            if (c == 'V') continue;
            if (floatCh != 0 && i >= floatFirst && i <= floatLast) {
                if (i == floatFirst) { out.append(' '); continue; }
                if (c != floatCh) { out.append(started ? c == 'B' ? ' ' : c : ' '); continue; }
                char d = digits.charAt(di++);
                if (!started && d == '0') { out.append(' '); continue; }
                if (!started) { out.setCharAt(out.length() - 1, floatSymbol(floatCh, neg)); started = true; }
                out.append(d);
                continue;
            }
            switch (c) {
                case '9' -> {
                    if (!started && floatCh != 0 && i > floatLast) out.setCharAt(out.length() - 1, floatSymbol(floatCh, neg));
                    started = true;
                    out.append(digits.charAt(di++));
                }
                case 'Z', '*' -> {
                    char d = digits.charAt(di++);
                    if (!started && d == '0' && (point < 0 || i < point)) out.append(c == '*' ? '*' : ' ');
                    else { started = true; out.append(d); }
                }
                case '.' -> {
                    if (!started && floatCh != 0 && i > floatLast) out.setCharAt(out.length() - 1, floatSymbol(floatCh, neg));
                    started = true;
                    out.append('.');
                }
                case ',' -> out.append(started ? ',' : suppress);
                case 'B' -> out.append(started ? ' ' : suppress);
                case '0' -> out.append(started ? '0' : suppress);
                case '/' -> out.append(started ? '/' : suppress);
                case '+' -> out.append(neg ? '-' : '+');
                case '-' -> out.append(neg ? '-' : ' ');
                case '$' -> out.append('$');
                case 'C' -> { out.append(neg ? "CR" : "  "); i++; }
                case 'D' -> { out.append(neg ? "DB" : "  "); i++; }
                default -> out.append(c);
            }
        }
        return out.toString();
    }

    private static char floatSymbol(char f, boolean neg) {
        return switch (f) {
            case '+' -> neg ? '-' : '+';
            case '-' -> neg ? '-' : ' ';
            default -> f;
        };
    }

    private static int lengthOf(String p) {
        int n = 0;
        for (int i = 0; i < p.length(); i++) if (p.charAt(i) != 'V') n++;
        return n;
    }

    /** A PICTURE string parsed as the COBOL compiler sizes it. */
    record Shape(boolean edited, int digits, int scale, boolean signed, String expanded) {
        private static final Map<String, Shape> CACHE = new ConcurrentHashMap<>();

        static Shape of(String picture) {
            return CACHE.computeIfAbsent(picture, Shape::parse);
        }

        static String expand(String pic) {
            StringBuilder sb = new StringBuilder();
            String p = pic.trim().toUpperCase();
            for (int i = 0; i < p.length(); i++) {
                char c = p.charAt(i);
                if (c == '(') {
                    int close = p.indexOf(')', i);
                    int count = Integer.parseInt(p.substring(i + 1, close).trim());
                    char prev = sb.charAt(sb.length() - 1);
                    for (int k = 1; k < count; k++) sb.append(prev);
                    i = close;
                } else sb.append(c);
            }
            return sb.toString();
        }

        private static Shape parse(String picture) {
            String p = expand(picture);
            if (p.indexOf('X') >= 0 || p.indexOf('A') >= 0) throw new IllegalArgumentException(picture + " is not a numeric PICTURE");
            boolean editSymbols = p.chars().anyMatch(c -> "Z*+-,.$B0/".indexOf(c) >= 0) || p.contains("CR") || p.contains("DB");
            if (!editSymbols) {
                boolean signed = p.startsWith("S");
                String body = p.replace("S", "");
                int digits = (int) body.chars().filter(c -> c == '9').count();
                int v = p.indexOf('V');
                int scale = v < 0 ? 0 : (int) p.substring(v + 1).chars().filter(c -> c == '9').count();
                int pCount = (int) body.chars().filter(c -> c == 'P').count();
                if (pCount > 0) scale = body.startsWith("P") || body.startsWith("VP") ? digits + pCount : -pCount;
                return new Shape(false, digits, scale, signed, p);
            }
            int digits = (int) p.chars().filter(c -> c == '9' || c == 'Z' || c == '*').count();
            for (char f : new char[]{'+', '-', '$'}) {
                int cnt = (int) p.chars().filter(c -> c == f).count();
                if (cnt > 1) digits += cnt - 1;
            }
            int dot = p.indexOf('.'), vv = p.indexOf('V');
            int dp = dot >= 0 ? dot : vv;
            int scale = dp < 0 ? 0 : (int) p.substring(dp + 1).chars().filter(c -> "9Z*+-$".indexOf(c) >= 0).count();
            if (p.endsWith("CR") || p.endsWith("DB"))
                scale = dp < 0 ? 0 : (int) p.substring(dp + 1, p.length() - 2).chars().filter(c -> c == '9' || c == 'Z' || c == '*').count();
            boolean signed = p.indexOf('+') >= 0 || p.indexOf('-') >= 0 || p.contains("CR") || p.contains("DB");
            return new Shape(true, digits, scale, signed, p);
        }
    }
}
